window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[2]="')\">\n          <div class=\"lin\"><div class=\"lico\"><img loading=\"lazy\" src=\"data:image/png;base64,\"></div><h4>Приманки</h4><p>рабочие и проверяемые</p></div>\n        </div>\n        <div class=\"library-tile\" data-goto=\"knowledge\" style=\"--tilebg:url('data:image/webp;base64,')\">\n          <div class=\"lin\"><div class=\"lico\"><img loading=\"lazy\" src=\"data:image/png;base64,\"></div><h4>База знаний</h4><p>принципы и методология</p></div>        </div>\n        <div class=\"library-tile\" data-goto=\"researchbase\" style=\"--tilebg:url('data:image/webp;base64,')\">\n          <div class=\"lin\"><div class=\"lico\"><img loading=\"lazy\" src=\"data:image/png;base64,\"></div><h4>Исследования</h4><p>гипотезы и источники</p></div>\n        </div>\n      </div>\n    </div>\n\n\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>ПОСЛЕДНИЕ РЫБАЛКИ</h3><div class=\"sub\">Три последние записи — в том же визуальном языке.</div></div>\n        <div class=\"linkish\" onclick=\"go('diary')\">Дневник →</div>\n      </div>\n      <div id=\"homeDiaryPreview\"></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>БЛИЖАЙШИЕ ТОЧКИ</h3><div class=\"sub\">Нижневартовск / Излучинск</div></div>\n        <div class=\"linkish\" onclick=\"go('map')\">Все точки →</div>\n      </div>\n      <div id=\"spotsBlock\"></div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-title\"><h3>МОИ РЕГИОНЫ</h3><div class=\"sub\">структура проекта</div></div>\n      <div class=\"region-chip-wrap\">\n        <div class=\"region-chip active\">Нижневартовск</div>\n        <div class=\"region-chip\">Астраханская область</div>\n        <div class=\"region-chip\">Дагестан</div>\n        <div class=\"region-chip\">Подмосковье</div>\n      </div>\n      <div id=\"regionsBlock\" class=\"region-slide\"></div>\n    </div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-map\">\n    <div class=\"card\">\n      <div class=\"card-title\">\n        <div><h3>КАРТА / РАБОЧИЕ ТОЧКИ</h3><div class=\"sub\">Подтверждённые координаты, структура точки и переход к маршруту.</div></div>\n      </div>\n      <div id=\"realFishingMap\" class=\"realmap\" aria-label=\"Карта рыболовных точек\"></div>\n      <div id=\"mapFallback\" class=\"point-legend\" style=\"display:none\">Карта не загрузилась. Ниже остаётся полный список точек с координатами и маршрутами.</div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\"><div><h3>ТОЧКИ НА КАРТЕ</h3><div class=\"sub\">Нажми карточку, чтобы открыть подробности.</div></div></div>\n      <div id=\"mapSpotsBlock\"></div>\n    </div>\n    <div class=\"card\">\n      <div class=\"card-title\"><h3>ПРИНЦИП</h3></div>\n      <div class=\"meta\">На карту попадают только координаты, которые подтверждены личным опытом или проверяемым источником. Неподтверждённые «красивые точки» приложение не придумывает.</div>\n    </div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-diary\">\n    <div class=\"trip-hero\" style=\"--tripbg:url('data:image/webp;base64,')\">\n      <div class=\"in\"><div class=\"k\">ЛИЧНАЯ ИСТОРИЯ</div><h2>Дневник рыбалки</h2><p>Каждая запись — отдельная карточка: место, результат, метод и вывод. Без таблиц и тесного текста сбоку.</p></div>\n    </div>\n    <div id=\"personalDiary\" class=\"pd-panel\">\n      <h3>Мои записи · на этом устройстве</h3>\n      <p class=\"pd-muted\">Записи и настройки снастей сохраняются в этом браузере. Для переноса на другой компьютер выгрузите копию личных данных.</p>\n      <div class=\"pd-actions\">\n        <button type=\"button\" class=\"pd-button\" data-action=\"new\">Новая запись</button>\n        <button type=\"button\" class=\"pd-button\" data-action=\"export\">Выгрузить копию</button>\n        <button type=\"button\" class=\"pd-button\" data-action=\"import\">Загрузить копию</button>\n        <button type=\"button\" class=\"pd-button\" data-action=\"archive\">Архив (0)</button>\n      </div>\n      <p role=\"status\" aria-live=\"polite\"></p>\n      <div class=\"pd-export-preview\" hidden>\n        <div class=\"pd-actions\"><a class=\"pd-button\" download>Скачать личные данные</a><button type=\"button\" class=\"pd-button\" data-action=\"copy-backup\">Скопировать содержимое</button></div>\n        <details><summary>Посмотреть содержимое копии</summary><textarea aria-label=\"Содержимое копии личных данных\" readonly rows=\"8\"></textarea></details>\n      </div>\n      <input type=\"file\" accept=\".json,application/json\" hidden aria-label=\"Файл копии личных данных\">\n      <div class=\"pd-import-preview\" hidden>\n        <p></p>\n        <button type=\"button\" class=\"pd-button\" data-action=\"confirm-import\">Объединить записи</button>\n        <button type=\"button\" class=\"pd-button\" data-action=\"cancel-import\">Отмена импорта</button>\n      </div>\n      <form hidden>\n        <h3>Новая рыбалка</h3>\n        <label>Дата<input type=\"date\" name=\"date\" required></label>\n        <label>Место<input name=\"location\" required maxlength=\"160\" autocomplete=\"off\"></label>\n        <label>Рыба<input name=\"fish\" maxlength=\"200\" autocomplete=\"off\"></label>\n        <label>Результат<textarea name=\"result\" required maxlength=\"1000\" rows=\"3\"></textarea></label>\n        <label>Метод<textarea name=\"method\" maxlength=\"1500\" rows=\"3\"></textarea></label>\n        <label>Вывод<textarea name=\"conclusion\" maxlength=\"3000\" rows=\"3\"></textarea></label>\n        <label>Заметки<textarea name=\"notes\" maxlength=\"6000\" rows=\"3\"></textarea></label>\n        <div class=\"pd-actions\">\n          <button type=\"submit\" class=\"pd-button\">Сохранить запись</button>\n          <button type=\"button\" class=\"pd-button\" data-action=\"cancel\">Отмена</button>\n        </div>\n      </form>\n      <div class=\"pd-list\"></div>\n    </div>\n    <h3>История из проекта</h3>\n    <p class=\"pd-muted\">Пять отчётов из прежней публичной версии. Новые записи хранятся выше и выгружаются отдельной копией.</p>\n    <div id=\"diaryBlock\"></div>\n  </section>\n\n  <section class=\"screen\" id=\"screen-fish\">\n  <div class=\"fish25-page\">\n    <div class=\"fish25-head\">\n      <div class=\"fish25-titleline\">\n        <div class=\"fish25-logo\" aria-hidden=\"true\"><svg viewBox=\"0 0 60 40\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"4\"><path d=\"M15 20C26 5 43 5 54 20C43 35 26 35 15 20L4 8v24z\"/><circle cx=\"42\" cy=\"17\" r=\"2\" fill=\"currentColor\" stroke=\"none\"/></svg></div>\n        <div>\n          <h2>Рыбы</h2>\n          <div class=\"fish25-sub\">Каталог видов, особенности, где и на что ловить</div>\n        </div>\n      </div>\n      <button class=\"fish25-round\" type=\"button\" onclick=\"document.getElementById('fishHomeSearch').focus()\">⌕</button>\n    </div>\n\n    <div class=\"fish25-search\">\n      <span>⌕</span>\n      <input id=\"fishHomeSearch\" placeholder=\"Поиск по названию, синониму, группе...\">\n      <button id=\"fishHomeClear\" type=\"button\">×</button>\n    </div>\n\n    <div class=\"fish25-scope\" id=\"fishScope\"></div>\n\n    <div class=\"fish25-section-title\">\n      <div><b>Мои целевые рыбы</b><span>приоритет для обучения и рекомендаций</span></div>\n    </div>\n    <div class=\"fish25-targets\" id=\"fish25Targets\"></div>\n\n    <div class=\"fish25-section-title\">\n      <div><b>Все рыбы по группам</b><span>открывается отдельный каталог группы</span></div>\n    </div>\n    <div class=\"fish25-groups\" id=\"fish25Groups\"></div>\n\n    <div id=\"fish25SearchResults\" class=\"fish25-search-results\" hidden></div>\n  </div>\n</section>\n\n\n\n  <section class=\"screen\" id=\"screen-waters\">\n    <div class=\"pagehero\" style=\"--pagebg:url('data:image/webp;base64,";